package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;
public class ReportingActivity extends Activity{
 private SharedPreferences p; private EditText total,newData,percent,sharing,partners,perception;
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);p=getSharedPreferences("reporting",0);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Suivi des résultats",27,true));r.addView(Ui.text(this,"Le programme exige un suivi des résultats après le projet. Préparez dès maintenant les indicateurs demandés afin de pouvoir produire la reddition de comptes.",13,false));LinearLayout box=Ui.panel(this);total=field(box,"Nombre total de données adaptées à une norme reconnue, par base de données","total");newData=field(box,"Nombre de nouvelles données standardisées ajoutées depuis la fin du projet","new");percent=field(box,"Pourcentage des données de l’organisation adaptées à une norme reconnue","percent");sharing=field(box,"Modalités de partage des données","sharing");partners=field(box,"Nombre de partenaires, clients ou personnes ayant accédé aux données","partners");perception=field(box,"Perception des résultats du projet","perception");Button save=Ui.primary(this,"Enregistrer le suivi");save.setOnClickListener(v->{save();Toast.makeText(this,"Suivi enregistré",Toast.LENGTH_SHORT).show();});box.addView(save);r.addView(box);r.addView(Ui.text(this,"Le bénéficiaire doit aussi produire le compte rendu demandé après le projet et le suivi des résultats exigé par le Ministère. Ces champs servent de préparation interne.",12,false));setContentView(Ui.wrap(this,r));}
 private EditText field(LinearLayout p,String h,String k){EditText e=Ui.field(this,h,this.p.getString(k,""));p.addView(e);return e;}
 private void save(){p.edit().putString("total",total.getText().toString()).putString("new",newData.getText().toString()).putString("percent",percent.getText().toString()).putString("sharing",sharing.getText().toString()).putString("partners",partners.getText().toString()).putString("perception",perception.getText().toString()).apply();}
}